mapper.select:
SELECT `r`.id as processInstanceId, `r`.`start_user_id`, `r`.`start_user_name`, `r`.`organization_id`, `r`.`organization_name`, `r`.`result` AS `status`, `r`.instance_name, `r`.`tenant` AS `tenant`, `r`.`instance_name` AS `apply_name`, `r`.`business_type` AS `business_type`, `p`.`PROC_INST_ID_` AS `proc_inst_id`, `p`.`START_TIME_` AS `submitedTime`, `p`.`END_TIME_` AS `end_time`, `t`.`ASSIGNEE_` AS `assignee`, `t`.`END_TIME_` AS `task_end_time`, v.TEXT_ as formNo, vt.NAME_ as activeNodeName FROM `act_hi_taskinst` `t` INNER JOIN `act_hi_procinst` `p` ON `t`.`PROC_INST_ID_` = `p`.`PROC_INST_ID_` INNER JOIN `process_instance_running` `r` ON `r`.`id` = `p`.`PROC_INST_ID_` inner join act_hi_varinst as v on r.id= v.PROC_INST_ID_ and v.NAME_='formNo' inner join act_hi_taskinst as vt on r.id= vt.PROC_INST_ID_
AND `t`.`END_TIME_` IS NOT NULL AND `t`.TASK_DEF_KEY_ != 'root' AND ((`t`.`DELETE_REASON_` != 'Multi-instance complete condition expression passed') OR (`t`.`DELETE_REASON_` IS NULL ))
AND `t`.`END_TIME_` IS NULL
`t`.`ASSIGNEE_`=#{userId}
and `p`.`START_TIME_` BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}
and r.business_type=#{query.businessType}
and r.application_code=#{query.applicationCode}
r.start_user_id =#{query.startUserId}
r.organization_id =#{query.organizationId}
group by r.id order by p.`START_TIME_` desc

SELECT r.id as processInstanceId, r.start_user_id, r.start_user_name, r.organization_id, r.organization_name, r.instance_name, COALESCE(`r`.`result`, 'ACTIVE') AS `status`, r.`tenant` AS `tenant`, r.`business_type` AS `business_type`, p.`START_TIME_` AS `submitedTime`, v.TEXT_ as formNo, vt.NAME_ as activeNodeName, r.create_time, r.update_time FROM `process_instance_running` r inner JOIN `act_hi_procinst` p ON r.`id` = p.`PROC_INST_ID_` inner JOIN `act_hi_taskinst` t ON t.`PROC_INST_ID_` = p.`PROC_INST_ID_` inner join act_hi_varinst as v on r.id= v.PROC_INST_ID_ and v.NAME_='formNo' left join act_hi_taskinst as vt on r.id= vt.PROC_INST_ID_ and vt.END_TIME_ is NULL
r.start_user_id =#{query.startUserId}
and p.`START_TIME_` BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}
and r.organization_id = #{query.organizationId}
and r.id in
#{id}
and r.business_type=#{query.businessType}
and r.application_code=#{query.applicationCode}
and r.result is null
and r.result = #{query.status}
group by r.id order by p.START_TIME_ desc

select id
from process_instance_running


        create_time BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}


        and application_code = #{query.applicationCode}


        and business_type = #{query.businessType}


        and organization_id = #{query.organizationId}




                and `result` is null


                and `result` = #{query.status}




        and start_user_name like concat('%',#{query.username},'%')


GROUP BY id
ORDER BY create_time DESC

select processInstanceId
from (SELECT r.id as processInstanceId,r.create_time
FROM `process_instance_running` r


        r.start_user_id = #{query.assignee}


        and `r`.create_time BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}


        and r.business_type= #{query.businessType}




                and `r`.`result` is null


                and `r`.`result` = #{query.status}




        and r.organization_id = #{query.organizationId}


        and r.application_code = #{query.applicationCode}


        and r.start_user_name like concat('%', #{query.username}, '%')


union
SELECT `r`.id as processInstanceId,r.create_time
FROM `act_hi_taskinst` `t`
INNER JOIN `process_instance_running` `r` ON `r`.`id` = `t`.`proc_inst_id_`
AND ((`t`.`DELETE_REASON_` != 'Multi-instance complete condition expression passed')
OR (`t`.`DELETE_REASON_` IS NULL ))


        and `r`.create_time BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}


        and r.business_type= #{query.businessType}




                and `r`.`result` is null


                and `r`.`result` = #{query.status}




        and r.application_code = #{query.applicationCode}


        and `t`.`assignee_` = #{query.assignee}


        and `r`.`start_user_id` = #{query.startUserId}


        and r.organization_id = #{query.organizationId}


        and r.start_user_name like concat('%', #{query.username}, '%')


UNION
SELECT `r`.id as process_instance_id,r.create_time
FROM `copy_log` `t`
inner JOIN `process_instance_running` `r` ON `r`.`id` = `t`.`process_instance_id`


        t.user_ids like concat('%', #{query.assignee}, '%')


        and `r`.create_time BETWEEN #{query.submitTime.begin} AND #{query.submitTime.end}


        and r.business_type= #{query.businessType}




                and `r`.`result` is null


                and `r`.`result` = #{query.status}




        and r.organization_id = #{query.organizationId}


        and `r`.`start_user_id` = #{query.startUserId}


        and r.start_user_name like concat('%', #{query.username}, '%')


        and r.application_code = #{query.applicationCode}


order by create_time desc
) a

